8		semver "github.com/Masterminds/semver/v3"
9	
10		"github.com/entireio/cli/cmd/entire/cli/checkpoint"
11	)
12	
13	const (
14		LogicalCheckpointVersionV1       = "1.0.0"
15		DefaultCheckpointVersionSelector = LogicalCheckpointVersionV1
16	)
17	
18	type CheckpointFeature string
19	
20	const FeatureBranchMetadata CheckpointFeature = "branch_metadata"
21	
22	type supportedCheckpointVersion struct {
23		version         *semver.Version
24		metadataVersion string
25		features        []CheckpointFeature
26	}
27	
28	var supportedCheckpointVersions = []supportedCheckpointVersion{
29		{
30			version:         mustSemver(LogicalCheckpointVersionV1),
31			metadataVersion: checkpoint.CheckpointVersionBranchV1,
32			features:        []CheckpointFeature{FeatureBranchMetadata},
33		},
34	}
35	
36	func ParseCheckpointVersionSelector(raw string) (*semver.Constraints, error) {
37		if strings.TrimSpace(raw) == "" {
38			return nil, fmt.Errorf("checkpoint_version %q is not a valid SemVer constraint", raw)
39		}
40		constraint, err := semver.NewConstraint(raw)
41		if err != nil {
42			return nil, fmt.Errorf("checkpoint_version %q is not a valid SemVer constraint: %w", raw, err)
43		}
44		return constraint, nil
45	}
46	
47	func ResolveCheckpointVersionSelector(raw string) (string, error) {
48		version, err := resolveCheckpointVersionSelector(raw, supportedCheckpointVersions)
49		if err != nil {
50			return "", err
51		}
52		return version.version.String(), nil
53	}
54	
55	// IsSupportedCheckpointVersion reports whether raw is a logical checkpoint version this CLI supports.
56	func IsSupportedCheckpointVersion(raw string) bool {
57		version, err := semver.StrictNewVersion(raw)
58		if err != nil {
59			return false
60		}
61		return slices.ContainsFunc(supportedCheckpointVersions, func(candidate supportedCheckpointVersion) bool {
62			return candidate.version.Equal(version)
63		})
64	}
65	
66	func LogicalVersionForCheckpointMetadata(raw string) (string, error) {
67		switch raw {
68		case "", checkpoint.CheckpointVersionBranchV1:
69			return LogicalCheckpointVersionV1, nil
70		}
71		version, err := semver.StrictNewVersion(raw)
72		if err != nil {
73			return "", fmt.Errorf("invalid checkpoint_version %q", raw)
74		}
75		return version.String(), nil
76	}
77	
78	func MetadataVersionForCheckpointVersion(raw string) (string, error) {
79		version, err := semver.StrictNewVersion(raw)
80		if err == nil {
81			if candidate, ok := findSupportedCheckpointVersion(version); ok {
82				return candidate.metadataVersion, nil
83			}
84		}
85		return "", fmt.Errorf("checkpoint_version %q is not supported by this Entire CLI", raw)
86	}
87	
88	func resolveCheckpointVersionSelector(raw string, candidates []supportedCheckpointVersion) (supportedCheckpointVersion, error) {
89		constraint, err := ParseCheckpointVersionSelector(raw)
90		if err != nil {
91			return supportedCheckpointVersion{}, err
92		}
93		var best supportedCheckpointVersion
94		var found bool
95		for _, candidate := range candidates {
96			if !constraint.Check(candidate.version) {
97				continue
98			}
99			if !found || best.version.LessThan(candidate.version) {
100				best = candidate
101				found = true
102			}
103		}
104		if found {
105			return best, nil
106		}
107		return supportedCheckpointVersion{}, fmt.Errorf("checkpoint_version %q is not supported by this Entire CLI", raw)
108	}
109	
110	func mustSemver(raw string) *semver.Version {
111		version, err := semver.StrictNewVersion(raw)
112		if err != nil {
113			panic(err)
114		}
115		return version
116	}
117	
118	func findSupportedCheckpointVersion(version *semver.Version) (supportedCheckpointVersion, bool) {
119		for _, candidate := range supportedCheckpointVersions {
120			if candidate.version.Equal(version) {
121				return candidate, true
122			}
123		}
124		return supportedCheckpointVersion{}, false
125	}
