13	func DefaultPolicy() Policy {
14		return Policy{
15			CheckpointVersion: DefaultCheckpointVersionSelector,
16		}
17	}
18	
19	func Normalize(policy Policy) Policy {
20		if policy.CheckpointVersion == "" {
21			policy.CheckpointVersion = DefaultCheckpointVersionSelector
22		}
23		return policy
24	}
25	
26	func EffectiveCheckpointVersion(policy Policy) (string, error) {
27		policy = Normalize(policy)
28		return ResolveCheckpointVersionSelector(policy.CheckpointVersion)
29	}
