31	func EffectiveCheckpointMetadataVersion(policy Policy) (string, error) {
32		version, err := EffectiveCheckpointVersion(policy)
33		if err != nil {
34			return "", err
35		}
36		return MetadataVersionForCheckpointVersion(version)
37	}
