39	func ValidatePolicy(policy Policy) error {
40		policy = Normalize(policy)
41	
42		_, err := ResolveCheckpointVersionSelector(policy.CheckpointVersion)
43		return err
44	}
45	
46	func HasUnsupportedCheckpointVersion(policy Policy) bool {
47		_, err := EffectiveCheckpointVersion(policy)
48		return err != nil
49	}
50	
51	func CanSatisfyPolicy(policy Policy) bool {
52		return ValidatePolicy(policy) == nil
53	}
54	
55	func PolicyEnablesFeature(policy Policy, feature CheckpointFeature) bool {
56		policy = Normalize(policy)
57		version, err := resolveCheckpointVersionSelector(policy.CheckpointVersion, supportedCheckpointVersions)
58		if err != nil {
59			return false
60		}
61		return slices.Contains(version.features, feature)
62	}
