64	func UnsupportedPolicyMessage(policy Policy, updateCommand string) string {
65		if CanSatisfyPolicy(policy) {
66			return ""
67		}
68	
69		var b strings.Builder
70		fmt.Fprintf(&b, "[entire] This repository requires checkpoint support newer than this Entire CLI.\n[entire] Upgrade Entire, then rerun the command:\n[entire]   %s\n", updateCommand)
71		details := unsupportedPolicyDetails(policy)
72		if len(details) == 0 {
73			return b.String()
74		}
75		b.WriteString("[entire] Details:\n")
76		for _, detail := range details {
77			fmt.Fprintf(&b, "[entire]   %s\n", detail)
