8	)
9	
10	type UpdateOptions struct {
11		CheckpointVersion    string
12		CheckpointVersionSet bool
13		Force                bool
14	}
15	
16	func Update(ctx context.Context, repo *git.Repository, target Target, opts UpdateOptions) (State, error) {
17		baseline, err := updateBaseline(ctx, repo, target)
18		if err != nil {
19			return State{}, err
20		}
21	
22		policy := baseline.Policy
23		if opts.CheckpointVersionSet {
24			policy.CheckpointVersion = opts.CheckpointVersion
25		}
26	
27		if err := rejectDowngrades(baseline.Policy, policy, opts); err != nil {
28			return State{}, err
29		}
30		if err := ValidatePolicy(policy); err != nil {
31			return State{}, err
32		}
33	
34		hash, err := WriteLocal(ctx, repo, baseline.Hash, policy)
35		if err != nil {
36			return State{}, err
37		}
38		return State{
39			Policy:     policy,
40			Source:     SourceLocal,
41			Hash:       hash,
42			RemoteHash: baseline.RemoteHash,
43		}, nil
44	}
45	
46	func updateBaseline(ctx context.Context, repo *git.Repository, target Target) (State, error) {
47		local, err := ReadLocal(ctx, repo)
48		if err != nil {
49			return State{}, err
50		}
51	
52		baseline, remoteFound, err := remoteBaseline(ctx, repo, target, local)
53		if err != nil {
54			return State{}, err
55		}
56		if !remoteFound || local.Hash == baseline.Hash {
57			return baseline, nil
58		}
59		if local.Hash.IsZero() {
60			return baseline, nil
61		}
62		localAncestor, err := isAncestorOf(ctx, repo, local.Hash, baseline.Hash)
63		if err != nil {
64			return State{}, err
65		}
66		if localAncestor {
67			return baseline, nil
68		}
69		baselineAncestor, err := isAncestorOf(ctx, repo, baseline.Hash, local.Hash)
70		if err != nil {
71			return State{}, err
72		}
73		if baselineAncestor {
74			local.RemoteHash = baseline.RemoteHash
75			return local, nil
76		}
77		return State{}, fmt.Errorf("local checkpoint policy %s diverges from remote %s; push or reconcile the policy before updating", local.Hash, baseline.RemoteHash)
78	}
79	
80	func rejectDowngrades(before, after Policy, opts UpdateOptions) error {
81		before = Normalize(before)
82		after = Normalize(after)
83	
84		if opts.Force {
85			return nil
86		}
87		if opts.CheckpointVersionSet {
88			if err := rejectCheckpointVersionDowngrade(before.CheckpointVersion, after.CheckpointVersion); err != nil {
89				return err
90			}
91		}
92		return nil
93	}
94	
95	func rejectCheckpointVersionDowngrade(beforeRaw, afterRaw string) error {
96		before, err := ResolveCheckpointVersionSelector(beforeRaw)
97		if err != nil {
98			return fmt.Errorf("checkpoint_version existing value %q: %w; pass --force to replace it", beforeRaw, err)
99		}
100		after, err := ResolveCheckpointVersionSelector(afterRaw)
101		if err != nil {
102			return fmt.Errorf("checkpoint_version: %w", err)
103		}
104		beforeVersion := mustSemver(before)
105		afterVersion := mustSemver(after)
106		if afterVersion.LessThan(beforeVersion) {
107			return fmt.Errorf("would downgrade checkpoint_version from %q to %q; pass --force to allow this", beforeRaw, afterRaw)
108		}
109		return nil
110	}
