49	func runCheckpointPolicy(cmd *cobra.Command, opts checkpointPolicyOptions) error {
50		ctx := cmd.Context()
51		if err := ctx.Err(); err != nil {
52			return NewSilentError(err)
53		}
54		repo, err := gitrepo.OpenCurrent(ctx)
55		if err != nil {
56			return checkpointPolicyError("open repository", err)
