58		defer repo.Close()
59	
60		target, err := checkpointpolicy.ResolveTarget(ctx)
61		if err != nil {
62			return checkpointPolicyError("resolve checkpoint policy remote", err)
63		}
64	
65		var state checkpointpolicy.State
66		checkpointVersionSet := cmd.Flags().Changed(checkpointVersionFlag)
67		if checkpointVersionSet {
68			state, err = checkpointpolicy.Update(ctx, repo, target, checkpointpolicy.UpdateOptions{
69				CheckpointVersion:    opts.version,
70				CheckpointVersionSet: checkpointVersionSet,
71				Force:                opts.force,
72			})
73			if err != nil {
74				return checkpointPolicyError("update checkpoint policy", err)
75			}
76			if err := checkpointpolicy.Push(ctx, target); err != nil {
77				return checkpointPolicyError("push checkpoint policy", err)
78			}
79			state.Source = checkpointpolicy.SourceRemote
80		} else {
81			state, err = checkpointpolicy.Sync(ctx, repo, target)
82			if err != nil {
83				return checkpointPolicyError("sync checkpoint policy", err)
84			}
85		}
86	
87		effectivePolicy := checkpointpolicy.Normalize(state.Policy)
88		fmt.Fprintf(cmd.OutOrStdout(), "checkpoint_version: %s\n", formatCheckpointVersionPolicyValue(state.Policy.CheckpointVersion, effectivePolicy.CheckpointVersion))
